import{_ as a,o as e,c as s,O as n}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"RAG 体系","description":"相关笔记：Elasticsearch","frontmatter":{"description":"相关笔记：Elasticsearch","tags":["AI Agent","大模型"]},"headers":[],"relativePath":"backend/AI-Agent/03-RAG体系.md","filePath":"backend/AI-Agent/03-RAG体系.md","lastUpdated":1793330679000}'),r={name:"backend/AI-Agent/03-RAG体系.md"};function d(o,t,l,p,c,i){return e(),s("div",null,t[0]||(t[0]=[n(`<h1 id="rag-体系" tabindex="-1">RAG 体系 <a class="header-anchor" href="#rag-体系" aria-label="Permalink to &quot;RAG 体系&quot;">​</a></h1><blockquote><p>相关笔记：<a href="./../../database/Elasticsearch">Elasticsearch</a></p></blockquote><blockquote><p>RAG 看起来就五步：切块、向量化、存、检索、拼。但真正决定效果的，全在细节里 —— <strong>90% 的 RAG 效果问题，都出在「切块」和「召回」</strong>，而不是模型。</p></blockquote><h2 id="_1-什么时候该用-rag" tabindex="-1">1. 什么时候该用 RAG <a class="header-anchor" href="#_1-什么时候该用-rag" aria-label="Permalink to &quot;1. 什么时候该用 RAG&quot;">​</a></h2><table><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>模型不知道的<strong>私有知识</strong>，且要<strong>及时更新</strong></td><td><strong>RAG</strong></td></tr><tr><td>模型能力/风格不对（不会说行话、格式总错）</td><td>微调</td></tr><tr><td>只是没说清</td><td>改 Prompt</td></tr><tr><td>知识量很小（几页），且不常变</td><td>直接塞进上下文</td></tr><tr><td>需要跨文档多跳推理</td><td>RAG + 查询改写/多轮检索</td></tr></tbody></table><p>判断口诀：<strong>「不知道」用 RAG，「不会说」才微调。</strong></p><h2 id="_2-离线管道-解析与切块" tabindex="-1">2. 离线管道：解析与切块 <a class="header-anchor" href="#_2-离线管道-解析与切块" aria-label="Permalink to &quot;2. 离线管道：解析与切块&quot;">​</a></h2><h3 id="_2-1-解析-最脏最累的一步" tabindex="-1">2.1 解析（最脏最累的一步） <a class="header-anchor" href="#_2-1-解析-最脏最累的一步" aria-label="Permalink to &quot;2.1 解析（最脏最累的一步）&quot;">​</a></h3><p>PDF 是 RAG 的第一大坑：<strong>表格丢结构、双栏串行、扫描件没文字</strong>。</p><table><thead><tr><th>内容类型</th><th>处理</th></tr></thead><tbody><tr><td>普通 PDF</td><td>优先用结构化解析（PyMuPDF / pdfplumber），别用粗略抽取</td></tr><tr><td>扫描件</td><td>OCR（PaddleOCR / 云服务），注意版面还原</td></tr><tr><td>表格</td><td>保留为 Markdown/HTML 表格，别拆成一段文字</td></tr><tr><td>Word/HTML</td><td>按标题层级解析，天然有结构</td></tr><tr><td>图片</td><td>多模态模型生成描述，或直接走多模态检索</td></tr></tbody></table><blockquote><p>一句经验：<strong>输入脏，后面全白搭</strong>。清洗（去页眉页脚、去乱码、合并断行）值得花掉整个项目 1/3 的时间。</p></blockquote><h3 id="_2-2-切块-chunking-策略" tabindex="-1">2.2 切块（chunking）策略 <a class="header-anchor" href="#_2-2-切块-chunking-策略" aria-label="Permalink to &quot;2.2 切块（chunking）策略&quot;">​</a></h3><table><thead><tr><th>策略</th><th>做法</th><th>适合</th></tr></thead><tbody><tr><td>定长 + 重叠</td><td>512 token，overlap 64</td><td>通用基线，简单可靠</td></tr><tr><td><strong>按结构切</strong></td><td>按标题层级/段落切，保留章节路径</td><td><strong>文档类首选</strong></td></tr><tr><td>语义切块</td><td>按句子嵌入的相似度找断点</td><td>长篇连续叙述</td></tr><tr><td>父子块（small-to-big）</td><td>用小块检索，命中后返回其父块</td><td>兼顾精度与上下文</td></tr><tr><td>句窗（sentence window）</td><td>命中句子后向前后扩 N 句</td><td>问答型语料</td></tr></tbody></table><p>三条硬经验：</p><ol><li><strong>一定要有 overlap</strong>（10%～20%），否则答案正好跨在边界上就丢了；</li><li><strong>每块带上「来源 + 章节标题」</strong>（元数据），既提升检索，又方便引用；</li><li><strong>块大小和问题粒度匹配</strong>：问「年假几天」用 200～500 token；问「这个方案怎么做」要大一些。</li></ol><h2 id="_3-embedding" tabindex="-1">3. Embedding <a class="header-anchor" href="#_3-embedding" aria-label="Permalink to &quot;3. Embedding&quot;">​</a></h2><table><thead><tr><th>关注点</th><th>说明</th></tr></thead><tbody><tr><td>模型选择</td><td>中文场景优先中文/多语言模型（如 bge-m3、text-embedding-3、qwen-embedding）</td></tr><tr><td>维度</td><td>768 / 1024 / 1536，维度越高越贵越慢</td></tr><tr><td><strong>归一化</strong></td><td>用余弦相似度前要确认模型输出是否已归一化</td></tr><tr><td><strong>对称 vs 非对称</strong></td><td>问题和文档不同分布，有的模型要求加 <code>query:</code> / <code>passage:</code> 前缀，<strong>不加会明显掉点</strong></td></tr><tr><td>一致性</td><td><strong>索引和查询必须用同一个模型</strong>，换模型要全量重建</td></tr></tbody></table><blockquote><p>注意：<strong>换了 embedding 模型 = 重建整个库</strong>。所以选型要在项目早期定，别中途换。</p></blockquote><h2 id="_4-索引与向量库" tabindex="-1">4. 索引与向量库 <a class="header-anchor" href="#_4-索引与向量库" aria-label="Permalink to &quot;4. 索引与向量库&quot;">​</a></h2><table><thead><tr><th>方案</th><th>适合</th><th>备注</th></tr></thead><tbody><tr><td><strong>Milvus</strong></td><td>百万～亿级</td><td>专业向量库，运维成本中高</td></tr><tr><td><strong>pgvector</strong></td><td>十万级、已有 PG</td><td>一库两用，最省心</td></tr><tr><td><strong>ES 8.x kNN</strong></td><td>已有 ES</td><td>天然支持 BM25 + 向量混合</td></tr><tr><td><strong>Qdrant / Weaviate</strong></td><td>中小规模</td><td>过滤能力强</td></tr><tr><td>Redis / FAISS</td><td>小规模 / 离线</td><td>Redis 复用现有栈，FAISS 不是服务</td></tr></tbody></table><p><strong>HNSW 参数（最常被问）</strong>：</p><table><thead><tr><th>参数</th><th>作用</th><th>调大</th></tr></thead><tbody><tr><td><code>M</code></td><td>每个节点的邻居数</td><td>召回↑、内存↑、建索引慢</td></tr><tr><td><code>ef_construction</code></td><td>建索引时的候选集</td><td>精度↑、建索引慢</td></tr><tr><td><code>ef_search</code></td><td>查询时的候选集</td><td>召回↑、延迟↑</td></tr></tbody></table><p><strong>没有通用参数</strong>，必须用自己的数据集画 recall-latency 曲线。</p><h2 id="_5-在线链路-召回才是命门" tabindex="-1">5. 在线链路：召回才是命门 <a class="header-anchor" href="#_5-在线链路-召回才是命门" aria-label="Permalink to &quot;5. 在线链路：召回才是命门&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">用户问题</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ Query 改写（多轮/口语化 → 完整查询）</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ 并行两路：向量检索（语义）+ BM25（关键词）</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ RRF 融合</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ 元数据过滤（租户/时间/权限）</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ Rerank 精排（cross-encoder，取 top 5）</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ 拼 Prompt（带编号 + 引用要求）</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ 模型生成 + 拒答兜底</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">用户问题</span></span>
<span class="line"><span style="color:#24292e;">  ↓ Query 改写（多轮/口语化 → 完整查询）</span></span>
<span class="line"><span style="color:#24292e;">  ↓ 并行两路：向量检索（语义）+ BM25（关键词）</span></span>
<span class="line"><span style="color:#24292e;">  ↓ RRF 融合</span></span>
<span class="line"><span style="color:#24292e;">  ↓ 元数据过滤（租户/时间/权限）</span></span>
<span class="line"><span style="color:#24292e;">  ↓ Rerank 精排（cross-encoder，取 top 5）</span></span>
<span class="line"><span style="color:#24292e;">  ↓ 拼 Prompt（带编号 + 引用要求）</span></span>
<span class="line"><span style="color:#24292e;">  ↓ 模型生成 + 拒答兜底</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_5-1-query-改写" tabindex="-1">5.1 Query 改写 <a class="header-anchor" href="#_5-1-query-改写" aria-label="Permalink to &quot;5.1 Query 改写&quot;">​</a></h3><p>多轮对话里「它多少钱」必须改写为「XX 套餐多少钱」才能召回。手段：用模型改写（多一次小调用）、或用规则拼接上一轮实体。</p><h3 id="_5-2-混合检索与-rrf" tabindex="-1">5.2 混合检索与 RRF <a class="header-anchor" href="#_5-2-混合检索与-rrf" aria-label="Permalink to &quot;5.2 混合检索与 RRF&quot;">​</a></h3><p>纯向量对<strong>专有名词/型号/编号</strong>很弱（语义相近但完全不同），所以要加关键词通道。</p><p><strong>RRF（Reciprocal Rank Fusion）</strong> 是把两路排名融合的标准做法，不需要归一化分数：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">score(d) = Σ  1 / (k + rank_i(d))       k 常取 60</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">score(d) = Σ  1 / (k + rank_i(d))       k 常取 60</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它只看名次不看分数，所以对两路分数量纲不一致的情况特别稳。</p><h3 id="_5-3-rerank" tabindex="-1">5.3 Rerank <a class="header-anchor" href="#_5-3-rerank" aria-label="Permalink to &quot;5.3 Rerank&quot;">​</a></h3><ul><li>粗排（向量/BM25）召回 <strong>50～100 条</strong>；</li><li>用 <strong>Cross-Encoder</strong>（如 bge-reranker）逐条打分，取 <strong>top 3～5</strong>；</li><li>代价是慢（要过一遍模型），所以只对少量候选做。</li></ul><p>实测经验：<strong>加 Rerank 通常是性价比最高的一步</strong>，尤其候选池大、问题口语化时。</p><h3 id="_5-4-元数据过滤与权限" tabindex="-1">5.4 元数据过滤与权限 <a class="header-anchor" href="#_5-4-元数据过滤与权限" aria-label="Permalink to &quot;5.4 元数据过滤与权限&quot;">​</a></h3><ul><li>一定要在<strong>检索阶段</strong>做租户/权限过滤，不能检索完再筛（会泄露、也会污染 topK）；</li><li>时间过滤对「最新政策」类问题很关键。</li></ul><h2 id="_6-生成-拼-prompt-与拒答" tabindex="-1">6. 生成：拼 Prompt 与拒答 <a class="header-anchor" href="#_6-生成-拼-prompt-与拒答" aria-label="Permalink to &quot;6. 生成：拼 Prompt 与拒答&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">资料（编号）：</span></span>
<span class="line"><span style="color:#e1e4e8;">[1] ...</span></span>
<span class="line"><span style="color:#e1e4e8;">[2] ...</span></span>
<span class="line"><span style="color:#e1e4e8;"></span></span>
<span class="line"><span style="color:#e1e4e8;">要求：</span></span>
<span class="line"><span style="color:#e1e4e8;">- 只依据资料回答，资料没有就说「资料中未提及」；</span></span>
<span class="line"><span style="color:#e1e4e8;">- 每个结论标注来源编号，如 [1]；</span></span>
<span class="line"><span style="color:#e1e4e8;">- 不要编造资料里没有的数字。</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">资料（编号）：</span></span>
<span class="line"><span style="color:#24292e;">[1] ...</span></span>
<span class="line"><span style="color:#24292e;">[2] ...</span></span>
<span class="line"><span style="color:#24292e;"></span></span>
<span class="line"><span style="color:#24292e;">要求：</span></span>
<span class="line"><span style="color:#24292e;">- 只依据资料回答，资料没有就说「资料中未提及」；</span></span>
<span class="line"><span style="color:#24292e;">- 每个结论标注来源编号，如 [1]；</span></span>
<span class="line"><span style="color:#24292e;">- 不要编造资料里没有的数字。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>拒答策略</strong>比「努力作答」更重要：空召回或相似度低于阈值时，直接说「没找到」，不要硬编。</p><h2 id="_7-评估-分两段看" tabindex="-1">7. 评估：分两段看 <a class="header-anchor" href="#_7-评估-分两段看" aria-label="Permalink to &quot;7. 评估：分两段看&quot;">​</a></h2><table><thead><tr><th>层次</th><th>指标</th><th>怎么测</th></tr></thead><tbody><tr><td><strong>检索</strong></td><td>Recall@K、MRR、NDCG、空召回率</td><td>人工标注「标准答案在第几块」</td></tr><tr><td><strong>生成</strong></td><td>忠实度（是否来自资料）、答案相关性、引用正确率</td><td>规则 + LLM-as-judge + 抽检</td></tr><tr><td><strong>端到端</strong></td><td>通过率、人工评分</td><td>固定评测集回归</td></tr></tbody></table><p><strong>建评测集的正确姿势</strong>：从真实日志里抽 50～200 条问题 → 标注答案所在文档/片段 → 每次改动跑一遍。</p><blockquote><p>记住顺序：<strong>先修检索，再修生成</strong>。召不回，模型再强也是编。</p></blockquote><h2 id="_8-进阶" tabindex="-1">8. 进阶 <a class="header-anchor" href="#_8-进阶" aria-label="Permalink to &quot;8. 进阶&quot;">​</a></h2><table><thead><tr><th>方向</th><th>解决什么</th></tr></thead><tbody><tr><td><strong>GraphRAG</strong></td><td>跨文档多跳、全局总结（实体关系图）</td></tr><tr><td><strong>Agentic RAG</strong></td><td>让 Agent 自己决定「检索几次、换什么查询」</td></tr><tr><td><strong>多向量 / ColBERT</strong></td><td>更细粒度匹配（token 级），但存储成本高</td></tr><tr><td><strong>增量更新与删除</strong></td><td>文档变更时按 docId 删旧块再写新块，别只追加</td></tr><tr><td><strong>缓存</strong></td><td>相同问题的检索结果缓存，省钱省延迟</td></tr></tbody></table><h2 id="_9-常见失败模式对照" tabindex="-1">9. 常见失败模式对照 <a class="header-anchor" href="#_9-常见失败模式对照" aria-label="Permalink to &quot;9. 常见失败模式对照&quot;">​</a></h2><table><thead><tr><th>现象</th><th>大概率原因</th><th>先查什么</th></tr></thead><tbody><tr><td>总是答「未提及」</td><td>空召回</td><td>切块粒度、embedding 前缀、相似度阈值</td></tr><tr><td>答得对但引用错</td><td>编号与片段对应错位</td><td>拼 Prompt 时的编号是否稳定</td></tr><tr><td>关键数字错</td><td>表格被拆坏</td><td>解析阶段</td></tr><tr><td>多轮对话越聊越偏</td><td>没做 Query 改写</td><td>改写链路</td></tr><tr><td>召回内容相关但不解决问题</td><td>缺 Rerank</td><td>加 cross-encoder</td></tr><tr><td>老文档还在被引用</td><td>没做删除/覆盖</td><td>增量更新逻辑</td></tr></tbody></table><h2 id="_10-速查表" tabindex="-1">10. 速查表 <a class="header-anchor" href="#_10-速查表" aria-label="Permalink to &quot;10. 速查表&quot;">​</a></h2><table><thead><tr><th>问题</th><th>一句话</th></tr></thead><tbody><tr><td>什么时候用 RAG</td><td>私有知识、要更新、不想微调</td></tr><tr><td>切块多大</td><td>200～500 token，overlap 10%～20%，按结构切优先</td></tr><tr><td>换 embedding 模型要做什么</td><td>全量重建索引</td></tr><tr><td>为什么加 BM25</td><td>专有名词/编号类查询向量检索不准</td></tr><tr><td>RRF 是什么</td><td>按名次融合，<code>Σ 1/(k+rank)</code>，k≈60</td></tr><tr><td>Rerank 值不值</td><td>通常最划算的一步，粗排 50 取 5</td></tr><tr><td>怎么评估 RAG</td><td>检索看 Recall@K，生成看忠实度</td></tr><tr><td>先优化哪</td><td>先检索后生成，空召回优先修</td></tr><tr><td>拒答重要吗</td><td>重要，空召回必须说「未提及」，别硬编</td></tr></tbody></table>`,50)]))}const g=a(r,[["render",d]]);export{b as __pageData,g as default};
